require_once __DIR__.'/maintenance.php';require_once __DIR__.'/session_bootstrap.php';if(empty($_SESSION['loggedin'])){header('Location: login.php');exit;}$db=new mysqli($DATABASE_HOST,$DATABASE_USER,$DATABASE_PASS,$DATABASE_NAME);if($db->connect_errno)exit('Database unavailable.');$db->set_charset('utf8mb4');$uid=(int)$_SESSION['id'];$q=$db->prepare('SELECT hostmode FROM accounts WHERE id=?');$q->bind_param('i',$uid);$q->execute();$q->bind_result($mode);$q->fetch();$q->close();if((int)$mode<1){http_response_code(403);exit('Host operator access required.');}$report=null;if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['prune']))$report=tt_prune_database($db,tt_db_target_bytes());$size=tt_db_size_bytes($db);$pct=tt_db_limit_bytes()>0?100*$size/tt_db_limit_bytes():0;function mbf($n){return number_format($n/1000000,2).' MB';}
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · Storage</title></head><body><nav class="navtop"><div><h1><a href="/">TABLETIME</a></h1><a href="federation_admin.php">Federation</a><a href="extend.php">Extend</a></div></nav><main class="content"><h2>Bounded database</h2><section class="card"><p><b><?=mbf($size)?></b> used of <?=mbf(tt_db_limit_bytes())?> (<?=number_format($pct,1)?>%).</p><p>Cleanup starts near <?=mbf(tt_db_soft_bytes())?>, targets <?=mbf(tt_db_target_bytes())?>, and new material writes are refused near <?=mbf(tt_db_hard_bytes())?> if pruning cannot make space. This uses nearly the full 100 MB allowance without intentionally crossing it.</p><p>Attachment upload cap: <b>250 KB</b>. Attachments belonging to pruned posts are removed with the post.</p><form method="post"><button name="prune" value="1">Run maintenance now</button></form><?php if($report):?><pre><?=htmlspecialchars(json_encode($report,JSON_PRETTY_PRINT))?></pre><?php endif;?></section></main></body></html>